@@ -0,0 +1,19 @@
+CREATE TABLE folders (
+  id INTEGER PRIMARY KEY,
+  parent INTEGER REFERENCES folders(id),
+  ordinal INTEGER DEFAULT NULL,
+  name TEXT,
+  flags INTEGER DEFAULT 0
+);
+
+-- These id values are deliberately out-of-order. It shouldn't matter.
+INSERT INTO folders (id, parent, name) VALUES
+  (5, 0, 'server1'),
+  (1, 5, 'INBOX'),
+  (3, 1, 'Sent'),
+  (9, 3, 'Junk'),
+  (7, 9, 'Trash'),
+  (4, 0, 'server2'),
+  (6, 4, 'folder'),
+  (2, 6, 'sub1'),
+  (8, 2, 'sub2');
diff --git a/mailnews/db/panorama/test/xpcshell/test_lookup.js b/mailnews/db/panorama/test/xpcshell/test_lookup.js
